export type ExplainMode = 'plain' | 'steps' | 'analogy' | 'compare' | 'scenario' | 'quiz';

export const EXPLAIN_MODES: { id: ExplainMode; label: string; hint: string }[] = [
  { id: 'plain', label: 'Plain language', hint: 'The idea in everyday words' },
  { id: 'steps', label: 'Step by step', hint: 'Broken into ordered parts' },
  { id: 'analogy', label: 'Everyday analogy', hint: 'Compared to something familiar' },
  { id: 'compare', label: 'Comparison table', hint: 'Side-by-side differences' },
  { id: 'scenario', label: 'Fictional scenario', hint: 'Practice clinical reasoning' },
  { id: 'quiz', label: 'Practice quiz', hint: 'Short questions with rationales' },
];

export interface QuizQuestion {
  prompt: string;
  options: string[];
  answer: number;
  rationale: string;
}

export interface Concept {
  id: string;
  title: string;
  category: string;
  summary: string;
  /** Lowercase words that link this concept to topics a student types. */
  keywords: string[];
  plain: string[];
  steps: { title: string; detail: string }[];
  analogy: { intro: string; pairs: [string, string][]; limits: string };
  compare: { caption: string; columns: string[]; rows: string[][] };
  scenario: { setup: string; prompts: { question: string; discussion: string }[] };
  quiz: QuizQuestion[];
  checkWith: string;
}

