export function findConceptForTopic(topic: string): Concept | undefined {
  const t = topic.toLowerCase();
  return CONCEPTS.find((c) => c.title.toLowerCase() === t || c.keywords.some((k) => t.includes(k) || (t.length >= 4 && k.includes(t))));
}
